scriptLabs.solution:
def score_user(baseline, observed):
    hits = []
    for axis, (mean, std) in baseline.items():
        z = (observed[axis] - mean) / std
        hits.append((axis, round(z, 1)))
    bad = [a for a, z in hits if abs(z) > 3]
    verdict = 'ESCALATE' if len(bad) >= 2 else 'monitor'
    return {'z_scores': dict(hits), 'deviating_axes': bad, 'verdict': verdict}

print(score_user(baseline, observed))

def triage(signed, known_vendor, business_need, scope):
    if signed and known_vendor and business_need:
        return {'decision': 'approve', 'rule': 'certificate', 'scope': scope}
    if business_need:
        return {'decision': 'ringfence', 'rule': 'hash', 'scope': scope,
                'leashes': ['app-to-app', 'file', 'registry', 'network']}
    return {'decision': 'deny', 'rule': 'none', 'scope': scope}

print(triage(True, True, True, 'finance-pcs'))
print(triage(False, False, True, 'warehouse-pcs'))
print(triage(False, False, False, 'all'))

