rule = {
    'title': 'Rare child process of Office application',
    'logsource': {'product': 'windows', 'category': 'process_creation'},
    'detection': {
        'parent_image|endswith': ['winword.exe', 'excel.exe', 'powerpnt.exe'],
        'child_image|not_in': ['splwow64.exe', 'conhost.exe'],
    },
    'severity': 'high',
}

def validate(rule):
    missing = [k for k in ('title', 'logsource', 'detection', 'severity') if k not in rule]
    return 'valid' if not missing else f'missing: {missing}'

print(validate(rule))

